/* PMK 138 — Restauration d’exemplaires
   Source métier conservée ; réglages communs dans PMK, sources locales conservées.
*/
(function(window){
    'use strict';
    if(!window.PMKPages || typeof window.PMKPages.register!=='function') return;
    const PAGE_SOURCE = "<style>\n  #uds-root {\n    --surface: #fff;\n    --line: #d5dee6;\n    --text: #1f3445;\n    --muted: #5f7486;\n    --primary: #6f8f32;\n    --success: #1e9365;\n    --danger: #9d2936;\n    --slate: #526d22;\n    max-width: 1600px;\n    margin: 0 auto 28px;\n    padding: 8px 4px 18px;\n    background: transparent;\n    font-family: system-ui, \"Segoe UI\", sans-serif;\n    color: var(--text);\n  }\n  #uds-root, #uds-root * { box-sizing: border-box; }\n  #uds-root h1 { margin: 0 0 8px; font-size: 22px; font-weight: 700; color: #526d22; }\n  #uds-root h3 { margin: 16px 0 8px; font-size: 16px; }\n  #uds-root .uds-sub { color: var(--muted); margin: 0 0 6px; font-size: 14px; }\n  #uds-root .uds-credit { color: var(--muted); margin: 0 0 16px; font-size: 13px; }\n  #uds-root fieldset { border: 1px solid var(--line); border-radius: 8px; margin: 0 0 12px; padding: 14px; background: var(--surface); }\n  #uds-root legend { font-weight: 700; font-size: 14px; color: #526d22; padding: 0 6px; }\n  #uds-root #uds-scanbar { display: flex; gap: 8px; align-items: flex-start; margin-bottom: 12px; flex-wrap: wrap; }\n  #uds-root #uds-barcode-input { flex: 1; min-width: 280px; padding: 8px; font-size: 15px; border: 1px solid #8ea0b0; border-radius: 4px; color: var(--text); background: #fff; }\n  #uds-root .uds-search-actions { display: flex; flex-direction: column; gap: 6px; }\n  #uds-root button {\n    padding: 8px 14px;\n    border: 1px solid var(--primary);\n    border-radius: 4px;\n    background: var(--primary);\n    color: #fff;\n    cursor: pointer;\n    font-size: 14px;\n  }\n  #uds-root .uds-btn--restore { background: var(--success); border-color: var(--success); }\n  #uds-root .uds-btn--issue { background: var(--primary); border-color: var(--primary); }\n  #uds-root .uds-btn--return, #uds-root .uds-btn--cycle { background: var(--slate); border-color: var(--slate); }\n  #uds-root .uds-btn--batch { background: #526d22; border-color: #526d22; }\n  #uds-root .uds-btn--quiet { background: #fff; color: var(--text); border-color: var(--line); }\n  #uds-root button:disabled { background: #e7edf2; color: var(--muted); border-color: var(--line); cursor: not-allowed; }\n  #uds-root #uds-message { font-weight: 700; min-height: 1.4em; margin: 8px 0; }\n  #uds-root #uds-message.uds-error { color: var(--danger); }\n  #uds-root #uds-message.uds-info { color: var(--primary); }\n  #uds-root #uds-cache-info { font-size: 13px; color: var(--muted); margin-bottom: 8px; }\n  #uds-root #uds-hint { font-size: 13px; color: var(--text); background: #f4f7fa; border-left: 3px solid var(--primary); padding: 8px 10px; margin-bottom: 12px; }\n  #uds-root .uds-table-wrap { overflow-x: auto; }\n  #uds-root table#uds-table { border-collapse: collapse; width: 100%; background: #fff; }\n  #uds-root table#uds-table th, #uds-root table#uds-table td { border: 1px solid var(--line); padding: 8px; font-size: 13px; vertical-align: top; }\n  #uds-root table#uds-table th { background: #f4f7fa; text-align: left; color: #526d22; }\n  #uds-root .uds-status { display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 12px; color: #fff; background: var(--muted); }\n  #uds-root .uds-status--wait { background: var(--muted); }\n  #uds-root .uds-status--ok { background: var(--success); }\n  #uds-root .uds-status--busy { background: #8a5a12; }\n  #uds-root .uds-status--error { background: var(--danger); }\n  #uds-root .uds-status--info { background: var(--slate); }\n  #uds-root .uds-log { max-height: 70px; overflow: auto; font-size: 12px; color: var(--muted); margin-top: 6px; }\n  #uds-root .uds-conflict { color: var(--danger); font-weight: 700; font-size: 13px; margin-top: 4px; }\n  #uds-root .uds-actions { display: flex; gap: 6px; flex-wrap: wrap; }\n  #uds-root #uds-actionsbar { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; margin-top: 8px; }\n  #uds-root .uds-note { margin: 8px 0 0; font-size: 13px; color: var(--muted); max-width: 46em; }\n  #uds-root #uds-target { margin: 0 0 10px; }\n  #uds-root #uds-check-all { width: 16px; height: 16px; }\n  #uds-root details { margin-left: 4px; }\n  #uds-root details summary { cursor: pointer; color: var(--primary); font-size: 14px; }\n  #uds-root details p { margin: 8px 0; font-size: 13px; color: var(--muted); max-width: 42em; }\n  #uds-root .uds-mode { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 0; }\n  #uds-root .uds-mode label { display: flex; align-items: center; gap: 6px; padding: 8px 10px; border: 1px solid var(--line); border-radius: 4px; cursor: pointer; background: #fff; font-size: 14px; }\n  #uds-root .uds-mode input { margin: 0; }\n  #uds-root .uds-mode label.uds-mode-active { border-color: var(--primary); background: #f4f7fa; }\n  #uds-root .uds-daterange { display: flex; gap: 12px; flex-wrap: wrap; align-items: end; margin-bottom: 8px; }\n  #uds-root .uds-daterange label { display: flex; flex-direction: column; gap: 4px; font-size: 13px; color: var(--text); }\n  #uds-root .uds-daterange input { padding: 8px; border: 1px solid #8ea0b0; border-radius: 4px; font-size: 14px; }\n  #uds-root #uds-app[hidden], #uds-root #uds-denied[hidden], #uds-root #uds-panel-barcode[hidden], #uds-root #uds-panel-dates[hidden] { display: none !important; }\n  #uds-root #uds-denied { border: 1px solid var(--danger); background: #fdf6f7; color: var(--danger); padding: 12px 14px; border-radius: 8px; margin-top: 12px; }\n  #uds-root #uds-auth-status { font-size: 13px; color: var(--muted); margin-bottom: 12px; }\n</style>\n<div id=\"uds-root\">\n<h1>Retrouver et restaurer des exemplaires</h1>\n<p class=\"uds-sub\">Recherche par <strong>code-barres</strong> ou par <strong>plage de dates</strong> &mdash; restauration native PimpMyKoha et cycle avanc&eacute; facultatif.</p>\n<p class=\"uds-credit\">Une partie de ce parcours s’inspire fortement du plugin UndeleteRecords (inLibro), développé par David Bourgault, Olivier Vézina, William Lavoie, Hammat Wele et Noah Tremblay.</p>\n<div id=\"uds-auth-status\">V&eacute;rification de la session Koha&hellip;</div>\n<div id=\"uds-denied\" hidden=\"\"><strong>Acc&egrave;s refus&eacute;.</strong> V&eacute;rifiez votre session et les droits configur&eacute;s pour cette page.</div>\n<div id=\"uds-app\" hidden=\"\">\n<div id=\"uds-hint\">Choisissez un mode de recherche. Le cycle pr&ecirc;t/retour exige une carte technique configur&eacute;e.</div>\n<fieldset><legend>1 · Choisir la recherche</legend>\n<div class=\"uds-mode\" id=\"uds-mode\"><label class=\"uds-mode-active\"> <input type=\"radio\" name=\"uds-search-mode\" value=\"barcode\" checked=\"checked\" /> Par code-barres </label> <label> <input type=\"radio\" name=\"uds-search-mode\" value=\"dates\" /> Par date de suppression </label></div>\n</fieldset><fieldset><legend>2 · Rechercher et examiner les exemplaires</legend>\n<div id=\"uds-panel-barcode\">\n<div id=\"uds-scanbar\"><textarea id=\"uds-barcode-input\" rows=\"3\" aria-label=\"Codes-barres des exemplaires &agrave; rechercher\" placeholder=\"Scannez (chaque code suivi d'Entr&eacute;e) ou collez une liste de codes-barres, un par ligne\"></textarea>\n<div class=\"uds-search-actions\"><button id=\"uds-search\" class=\"uds-btn uds-btn--load\">Rechercher</button></div>\n</div>\n</div>\n<div id=\"uds-panel-dates\" hidden=\"\">\n<div class=\"uds-mode\" id=\"uds-target\"><label class=\"uds-mode-active\"> <input type=\"radio\" name=\"uds-date-target\" value=\"items\" checked=\"checked\" /> Exemplaires </label> <label> <input type=\"radio\" name=\"uds-date-target\" value=\"biblios\" /> Notices </label></div>\n<p id=\"uds-target-note\" class=\"uds-note\">Les exemplaires sont les documents. Si leur notice est aussi supprimée, elle est restaurée avec eux.</p>\n<div class=\"uds-daterange\"><label>Du <input type=\"date\" id=\"uds-from-date\" /> </label> <label>Au <input type=\"date\" id=\"uds-to-date\" /> </label> <button id=\"uds-search-dates\" class=\"uds-btn uds-btn--load\">Charger les exemplaires</button></div>\n<p class=\"uds-note\">La date de fin peut rester vide : la recherche va jusqu’à maintenant.</p>\n</div>\n<div id=\"uds-cache-info\">Choisissez un mode puis lancez une recherche.</div>\n\n<p id=\"uds-message\"></p>\n<div class=\"uds-table-wrap\"><table id=\"uds-table\">\n<thead>\n<tr>\n<th><input type=\"checkbox\" id=\"uds-check-all\" aria-label=\"Cocher toutes les lignes à restaurer\" /></th>\n<th>Code-barres</th>\n<th>Titre / Auteur</th>\n<th>ISBN / ISSN</th>\n<th>Notice</th>\n<th>Supprim&eacute; le</th>\n<th>Statut</th>\n<th>Statut perdu</th>\n<th>Traitement</th>\n<th>Actions</th>\n</tr>\n</thead>\n<tbody id=\"uds-table-body\"></tbody>\n</table></div><h3>3 · Restaurer les dossiers examin&eacute;s</h3><div id=\"uds-actionsbar\"><button id=\"uds-select-all\" class=\"uds-btn uds-btn--quiet\">Tout cocher</button> <button id=\"uds-batch-restore\" class=\"uds-btn uds-btn--restore\">Restaurer la s&eacute;lection</button> <button id=\"uds-batch-pipeline\" class=\"uds-btn uds-btn--cycle\">Prêter et retourner la sélection</button></div>\n<p class=\"uds-note\">« Prêter et retourner » restaure d’abord chaque exemplaire encore supprimé, avec sa notice si elle l’est aussi, puis fait le prêt et le retour. Prêter et Retourner restent disponibles séparément.</p>\n</fieldset></div>\n</div>\n<script>\n(function () {\n  \"use strict\";\n\n  /* ======================================================================\n   * CONFIGURATION — à adapter à votre établissement\n   * ==================================================================== */\n  const CONFIG = {\n    // Accès : seuls ces usernames Koha (data-loggedinusername) voient le formulaire\n    allowedUsernames: [],\n\n    // Carte lecteur pour les prêts (cardnumber Koha) — résolue en patron_id via l'API REST\n    patronCardnumber: \"\",\n\n    // Recherche native : /api/v1/contrib/pmk/restoration/deleted-items et deleted-biblios.\n    // Le parcours s’inspire de Koha::Plugin::UndeleteRecords (inLibro).\n    pluginClass: \"\",\n    runUrl: \"/cgi-bin/koha/plugins/run.pl\",\n\n    // Plage de dates par défaut (mode dates)\n    defaultLookbackDays: 90,\n\n    // API REST Koha (prêt / résolution de la carte)\n    restBase: \"/api/v1\",\n    libraryId: null, // ex. \"BP\" si besoin ; null = biblio de la session staff\n  };\n  const pageTools=window.PMKPagesSettings,pageContext=pageTools?.contextFor('restore-deleted-items');\n  Object.assign(CONFIG,pageTools?.runtime('restore-deleted-items',CONFIG)||{});\n  const pageFetch=(url,options)=>pageTools?pageTools.request('restore-deleted-items',url,options,pageContext):window.fetch(url,options);\n\n\n  // Les explications suivent les paramètres effectifs de cette installation.\n  const allowedNames=Array.isArray(CONFIG.allowedUsernames)?CONFIG.allowedUsernames:[];\n  const card=String(CONFIG.patronCardnumber||'').trim();\n  const accessHint=allowedNames.length?'Accès limité à '+allowedNames.join(', ')+'.':'Accès selon les droits Koha configurés pour cette page.';\n  const loanHint=card?'Les prêts/retours utilisent la carte '+card+'.':'Renseignez une carte technique avant un traitement avec prêt/retour.';\n  document.querySelector('.uds-sub').textContent='Recherche par code-barres ou par date de suppression. Un exemplaire restauré ramène sa notice si elle est supprimée. Une notice restaurée seule ne ramène pas ses exemplaires. '+loanHint;\n  document.getElementById('uds-hint').textContent='Deux recherches : le code-barres, ou une date. Dans la date, choisissez les exemplaires ou les notices. '+loanHint+' '+accessHint;\n  document.getElementById('uds-denied').textContent='Accès refusé. '+accessHint+' Vérifiez votre session et les droits de cette page.';\n\n  // IMPORTANT : même domaine que Koha + session staff ouverte.\n\n  const rows = new Map();\n\n  function esc(str) {\n    if (str === null || str === undefined) return \"\";\n    return String(str).replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\").replace(/\"/g, \"&quot;\");\n  }\n\n  function txt(node) {\n    return node ? node.textContent.replace(/\\s+/g, \" \").trim() : \"\";\n  }\n\n  function showMessage(text, kind) {\n    const el = document.getElementById(\"uds-message\");\n    el.textContent = text;\n    el.className = kind ? \"uds-\" + kind : \"\";\n  }\n\n  function setStatus(barcode, label, kind) {\n    const row = rows.get(barcode);\n    if (!row) return;\n    const badge = row.el.querySelector(\".uds-status\");\n    badge.textContent = label;\n    badge.className = \"uds-status uds-status--\" + (kind || \"wait\");\n  }\n\n  function syncSelectAllLabel() {\n    const boxes = Array.from(document.querySelectorAll(\"#uds-table-body input[type=checkbox]\"));\n    const all = boxes.length > 0 && boxes.every((box) => box.checked);\n    const button = document.getElementById(\"uds-select-all\");\n    if (button) button.textContent = all ? \"Tout décocher\" : \"Tout cocher\";\n    const head = document.getElementById(\"uds-check-all\");\n    if (head) {\n      head.checked = all;\n      head.indeterminate = boxes.some((box) => box.checked) && !all;\n    }\n  }\n\n  function setAllChecked(checked) {\n    const boxes = Array.from(document.querySelectorAll(\"#uds-table-body input[type=checkbox]\"));\n    if (!boxes.length) {\n      showMessage(\"Aucun exemplaire dans la liste.\", \"info\");\n      syncSelectAllLabel();\n      return;\n    }\n    boxes.forEach((box) => { box.checked = checked; });\n    syncSelectAllLabel();\n  }\n\n  function log(barcode, message) {\n    const row = rows.get(barcode);\n    if (!row) return;\n    const logEl = row.el.querySelector(\".uds-log\");\n    const line = document.createElement(\"div\");\n    line.textContent = message;\n    logEl.appendChild(line);\n    logEl.scrollTop = logEl.scrollHeight;\n  }\n\n  function extractErrorSnippet(html) {\n    try {\n      const doc = new DOMParser().parseFromString(html, \"text/html\");\n      const pre = doc.querySelector(\"pre\");\n      const h1 = doc.querySelector(\"h1\");\n      const title = doc.querySelector(\"title\");\n      const source = (pre && pre.textContent)\n        || (h1 && h1.textContent)\n        || (title && title.textContent)\n        || (doc.body ? doc.body.textContent : html);\n      return source.replace(/\\s+/g, \" \").trim().slice(0, 400);\n    } catch (e) {\n      return String(html).replace(/\\s+/g, \" \").trim().slice(0, 400);\n    }\n  }\n\n  function looksLikeLoginPage(html) {\n    return /name=[\"']userid[\"']/i.test(html) || /opac-auth|intranet-auth|Log in to Koha/i.test(html);\n  }\n\n\n  /* ======================================================================\n   * 1) RECHERCHE PAR CB — guided_reports.pl (export CSV)\n   *    Même contrat que l'URL qui marche :\n   *    ?id=5230&param_name=barcode|list&sql_params=...&op=run\n   *    Ici : op=export&format=csv pour parser le résultat.\n   *    (svc/report avec param_names ne renvoie pas les mêmes résultats\n   *    sur cette instance.)\n   * ==================================================================== */\n  function normalizeReportRow(row) {\n    const pickObj = (obj, ...keys) => {\n      for(const key of keys){const mapped=CONFIG.reportColumns?.[key];if(mapped && obj[mapped]!==undefined && obj[mapped]!==null)return obj[mapped];}\n      for (const k of keys) {\n        if (obj[k] !== undefined && obj[k] !== null && String(obj[k]) !== \"\") return obj[k];\n      }\n      return \"\";\n    };\n\n    if (Array.isArray(row)) {\n      // Ordre conseillé du SELECT :\n      // itemnumber, barcode, title, author, isbn, issn, biblionumber, timestamp,\n      // conflict, notforloan/statut, itemlost/statut_perdu\n      return {\n        itemnumber: String(row[0] ?? \"\"),\n        barcode: String(row[1] ?? \"\"),\n        title: String(row[2] ?? \"\"),\n        author: String(row[3] ?? \"\"),\n        isbn: String(row[4] ?? \"\"),\n        issn: String(row[5] ?? \"\"),\n        biblionumber: String(row[6] ?? \"\"),\n        timestamp: String(row[7] ?? \"\"),\n        conflict: !!(row[8] && String(row[8]) !== \"0\"),\n        statut: String(row[9] ?? \"\"),\n        statut_perdu: String(row[10] ?? \"\"),\n      };\n    }\n\n    const conflictRaw = pickObj(row, \"conflict\", \"Conflict\");\n    return {\n      itemnumber: String(pickObj(row, \"itemnumber\", \"Itemnumber\")),\n      barcode: String(pickObj(row, \"barcode\", \"Barcode\")),\n      title: String(pickObj(row, \"title\", \"Title\")),\n      author: String(pickObj(row, \"author\", \"Author\")),\n      isbn: String(pickObj(row, \"isbn\", \"Isbn\", \"ISBN\")),\n      issn: String(pickObj(row, \"issn\", \"Issn\", \"ISSN\")),\n      biblionumber: String(pickObj(row, \"biblionumber\", \"Biblionumber\")),\n      timestamp: String(pickObj(row, \"timestamp\", \"Timestamp\")),\n      conflict: !!(conflictRaw && String(conflictRaw) !== \"0\"),\n      statut: String(pickObj(row, \"statut\", \"status\", \"notforloan\", \"Notforloan\", \"withdrawn\", \"Withdrawn\")),\n      statut_perdu: String(pickObj(row, \"statut_perdu\", \"itemlost\", \"Itemlost\", \"lost\", \"lost_status\", \"Lost\")),\n    };\n  }\n\n  function chunkArray(arr, size) {\n    const out = [];\n    const n = Math.max(1, size || arr.length || 1);\n    for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));\n    return out;\n  }\n\n  /** Parse CSV Koha (délimiteur , ou ; ; gère guillemets et BOM). */\n  function parseCsv(text) {\n    let raw = String(text || \"\").replace(/^\\uFEFF/, \"\");\n    if (!raw.trim()) return [];\n\n    // Erreurs d'export éventuelles en fin de fichier\n    raw = raw.replace(/^# ERROR:.*$/gm, \"\").trim();\n    if (!raw) return [];\n\n    const firstLine = raw.split(/\\r?\\n/, 1)[0] || \"\";\n    const delimiter = (firstLine.split(\";\").length > firstLine.split(\",\").length) ? \";\" : \",\";\n\n    const rows = [];\n    let i = 0;\n    let field = \"\";\n    let row = [];\n    let inQuotes = false;\n\n    while (i < raw.length) {\n      const c = raw[i];\n      if (inQuotes) {\n        if (c === '\"') {\n          if (raw[i + 1] === '\"') { field += '\"'; i += 2; continue; }\n          inQuotes = false; i++; continue;\n        }\n        field += c; i++; continue;\n      }\n      if (c === '\"') { inQuotes = true; i++; continue; }\n      if (c === delimiter) { row.push(field); field = \"\"; i++; continue; }\n      if (c === \"\\n\" || (c === \"\\r\" && raw[i + 1] === \"\\n\")) {\n        if (c === \"\\r\") i++;\n        row.push(field); field = \"\";\n        if (row.some((cell) => String(cell).trim() !== \"\")) rows.push(row);\n        row = []; i++; continue;\n      }\n      if (c === \"\\r\") {\n        row.push(field); field = \"\";\n        if (row.some((cell) => String(cell).trim() !== \"\")) rows.push(row);\n        row = []; i++; continue;\n      }\n      field += c; i++;\n    }\n    row.push(field);\n    if (row.some((cell) => String(cell).trim() !== \"\")) rows.push(row);\n    return rows;\n  }\n\n  function rowsFromCsv(text) {\n    const table = parseCsv(text);\n    if (table.length === 0) return [];\n\n    const header = table[0].map((h) => String(h).trim().toLowerCase());\n    const looksLikeHeader = header.some((h) =>\n      /itemnumber|barcode|title|author|biblionumber|timestamp|conflict|itemlost|notforloan|statut|withdrawn|lost/.test(h)\n    );\n    const dataRows = looksLikeHeader ? table.slice(1) : table;\n\n    if (looksLikeHeader) {\n      return dataRows.map((cells) => {\n        const obj = {};\n        header.forEach((h, idx) => { obj[h] = cells[idx] ?? \"\"; });\n        // aliases courants\n        if (obj.itemnumber === undefined && cells[0] !== undefined) obj.itemnumber = cells[0];\n        if (obj.barcode === undefined && cells[1] !== undefined) obj.barcode = cells[1];\n        return normalizeReportRow(obj);\n      }).filter((r) => r.barcode);\n    }\n\n    return dataRows.map((cells) => normalizeReportRow(cells)).filter((r) => r.barcode);\n  }\n\n  async function lookupBarcodeBatch(barcodes) {\n    // guided_reports.pl?id=5230&param_name=barcode|list&sql_params=...&op=export&format=csv\n    const url = new URL(CONFIG.reportUrl, window.location.origin);\n    url.searchParams.set(\"id\", String(CONFIG.reportIdBarcode));\n    url.searchParams.set(\"op\", \"export\");\n    url.searchParams.set(\"format\", \"csv\");\n    url.searchParams.append(\"param_name\", CONFIG.reportParamName);\n    url.searchParams.append(\"sql_params\", barcodes.join(\"\\r\\n\"));\n\n    const resp = await pageFetch(url.toString(), {\n      method: \"GET\",\n      credentials: \"same-origin\",\n      headers: { Accept: \"text/csv,application/csv,text/plain,*/*\" },\n    });\n    const raw = await resp.text();\n\n    if (resp.status === 401 || looksLikeLoginPage(raw)) {\n      throw new Error(\"Session Koha absente — reconnectez-vous sur l'intranet.\");\n    }\n    if (!resp.ok) {\n      throw new Error(\"guided_reports export HTTP \" + resp.status + \" — \" + extractErrorSnippet(raw));\n    }\n    if (looksLikeLoginPage(raw) || /<html[\\s>]/i.test(raw)) {\n      throw new Error(\n        \"Export CSV refusé (page HTML reçue). Vérifiez la session staff et réessayez. \" +\n        \"URL test : \" + url.toString()\n      );\n    }\n\n    return rowsFromCsv(raw);\n  }\n\n  async function lookupByBarcodes(barcodes) {\n    const batches = chunkArray(barcodes, CONFIG.reportBatchSize);\n    const items = [];\n    for (let i = 0; i < batches.length; i++) {\n      document.getElementById(\"uds-cache-info\").textContent =\n        \"Appel du rapport \" + CONFIG.reportIdBarcode + \" — lot \" + (i + 1) + \"/\" + batches.length +\n        \" (\" + batches[i].length + \" CB)…\";\n      const batchItems = await lookupBarcodeBatch(batches[i]);\n      items.push.apply(items, batchItems);\n    }\n\n    const foundSet = new Set(items.map((it) => it.barcode));\n    const notFound = barcodes.filter((b) => !foundSet.has(b));\n    return { items, not_found: notFound };\n  }\n\n  /* ======================================================================\n   * 1b) RECHERCHE PAR DATES — rapport SQL 5231\n   * ==================================================================== */\n  function todayISO() {\n    return new Date().toISOString().slice(0, 10);\n  }\n\n  function daysAgoISO(days) {\n    const d = new Date();\n    d.setUTCDate(d.getUTCDate() - days);\n    return d.toISOString().slice(0, 10);\n  }\n\n  async function lookupByDateRange(fromDate, toDate) {\n    // guided_reports.pl?id=5231&param_name=Du|date&sql_params=...&param_name=Au|date&sql_params=...\n    const url = new URL(CONFIG.reportUrl, window.location.origin);\n    url.searchParams.set(\"id\", String(CONFIG.reportIdDates));\n    url.searchParams.set(\"op\", \"export\");\n    url.searchParams.set(\"format\", \"csv\");\n    url.searchParams.append(\"param_name\", CONFIG.reportDateFromParam);\n    url.searchParams.append(\"sql_params\", fromDate);\n    url.searchParams.append(\"param_name\", CONFIG.reportDateToParam);\n    url.searchParams.append(\"sql_params\", toDate);\n\n    document.getElementById(\"uds-cache-info\").textContent =\n      \"Appel du rapport \" + CONFIG.reportIdDates + \" — \" + fromDate + \" → \" + toDate + \"…\";\n\n    const resp = await pageFetch(url.toString(), {\n      method: \"GET\",\n      credentials: \"same-origin\",\n      headers: { Accept: \"text/csv,application/csv,text/plain,*/*\" },\n    });\n    const raw = await resp.text();\n\n    if (resp.status === 401 || looksLikeLoginPage(raw)) {\n      throw new Error(\"Session Koha absente — reconnectez-vous sur l'intranet.\");\n    }\n    if (!resp.ok) {\n      throw new Error(\"guided_reports export HTTP \" + resp.status + \" — \" + extractErrorSnippet(raw));\n    }\n    if (looksLikeLoginPage(raw) || /<html[\\s>]/i.test(raw)) {\n      throw new Error(\n        \"Export CSV refusé (page HTML reçue). Vérifiez la session staff. \" +\n        \"URL test : \" + url.toString()\n      );\n    }\n\n    return rowsFromCsv(raw);\n  }\n\n  /* ======================================================================\n   * 2) RESTAURATION — API native PMK, aperçu et contrôle transactionnel\n   * ==================================================================== */\n  const restoreErrors={metadata_invalid:'La notice MARC archivée est invalide. Aucune restauration n’a été conservée.',forbidden:'Vos droits ou les comptes autorisés ne permettent pas cette restauration.',branch_forbidden:'Vous ne pouvez pas modifier les exemplaires de ce site.',cataloguing_permission_required:'Restaurer la notice exige aussi le droit de modifier le catalogue.',deleted_item_missing:'Cet exemplaire ne figure plus dans les exemplaires supprimés.',deleted_biblio_missing:'Cette notice ne figure plus dans les notices supprimées.',biblio_id_in_use:'Cette notice est déjà active.',invalid_date:'La date indiquée n’est pas utilisable.',invalid_range:'Indiquez une date de début, ou au plus 100 codes-barres.',invalid_kind:'Ce type de restauration n’est pas reconnu.',item_id_in_use:'Cet identifiant appartient déjà à un exemplaire actif.',preview_changed:'Les données ont changé depuis l’aperçu. Analysez à nouveau avant de confirmer.',barcode_conflict:'Le code-barres est déjà utilisé.',barcode_too_long:'Un code-barres dépasse 20 caractères, la longueur maximale acceptée par Koha.',biblio_missing:'La notice d’origine est introuvable.',biblioitem_missing:'Les informations bibliographiques d’origine sont introuvables.',biblioitem_mismatch:'Le rattachement bibliographique est incohérent.',metadata_missing:'La notice MARC d’origine est absente.',library_missing:'Un site de l’exemplaire supprimé n’existe plus dans Koha.',deleted_item_on_loan:'L’archive porte encore une date de prêt. Un contrôle manuel est nécessaire.',restore_conflict:'Un conflit empêche la restauration ; aucune modification de ce traitement n’est conservée.',item_changed:'L’exemplaire déjà restauré a été modifié. Vérifiez son état dans Koha.',schema_mismatch:'Les colonnes de l’archive et de Koha diffèrent. La restauration est arrêtée pour préserver les données.',verification_failed:'La relecture ne confirme pas toutes les valeurs. La restauration a été annulée.'};\n  async function restorationRequest(id,options={}) {\n    const response=await pageFetch('/api/v1/contrib/pmk/restoration/items/'+encodeURIComponent(id),{\n      credentials:'same-origin',...options,headers:{Accept:'application/json','Content-Type':'application/json','X-PMK-Request':'1'}});\n    const value=await response.json();\n    if(!response.ok){const error=new Error(restoreErrors[value.error]||('Restauration indisponible (HTTP '+response.status+').'));error.code=value.error;throw error;}\n    return value;\n  }\n  async function confirmRestoration(plans, pipeline=false) {\n    const question=plans.map(p=>p.kind==='biblio'?'Notice '+p.biblio_id+' — '+(p.title||'Sans titre')+'\\nSeule la notice est restaurée. Ses exemplaires supprimés restent supprimés.':'Exemplaire '+p.item_id+' — '+(p.title||'Sans titre')+'\\nCode-barres : '+(p.barcode_before||'Sans code-barres')+(p.barcode_conflict?' → '+p.barcode_after:'')+(p.restore_biblio?'\\nLa notice '+p.biblio_id+' sera également restaurée.':'')).join('\\n\\n');\n    const summary=question+(pipeline?'\\n\\nChaque exemplaire encore supprimé est d’abord restauré. Si sa notice est supprimée, elle l’est aussi. Il est ensuite prêté puis retourné avec la carte '+CONFIG.patronCardnumber+'.':'');\n    const review={title:pipeline?'Prêter et retourner':'Restaurer les exemplaires examinés',summary,changes:[]};\n    return window.PMKWorkbench?await PMKWorkbench.confirm(review):window.confirm(summary+'\\n\\nConfirmer ?');\n  }\n  async function applyRestoration(plan) {\n    const result=await restorationRequest(plan.item_id,{method:'POST',body:JSON.stringify({fingerprint:plan.fingerprint,confirmed:true,barcode:plan.barcode_before||''})});\n    if(!result.restored||Number(result.item_id)!==Number(plan.item_id))throw new Error('La restauration n’a pas été confirmée.');\n    return result;\n  }\n\n  /* ======================================================================\n   * 3) PRÊT / RETOUR — API REST uniquement\n   * ==================================================================== */\n  let cachedPatronId = null;\n  let cachedCsrf = null;\n\n  async function fetchFreshCsrfToken() {\n    // Jeton CSRF intranet pour les prêts et retours REST natifs\n    const candidates = [\n      \"/cgi-bin/koha/mainpage.pl\",\n    ];\n    let lastErr = null;\n    for (const url of candidates) {\n      try {\n        const resp = await pageFetch(url, { credentials: \"same-origin\" });\n        const html = await resp.text();\n        if (!resp.ok) {\n          lastErr = new Error(\"HTTP \" + resp.status + \" — \" + extractErrorSnippet(html));\n          continue;\n        }\n        if (looksLikeLoginPage(html)) {\n          throw new Error(\"Session Koha absente — reconnectez-vous sur l'intranet.\");\n        }\n        const doc = new DOMParser().parseFromString(html, \"text/html\");\n        const input = doc.querySelector('input[name=\"csrf_token\"]');\n        const meta = doc.querySelector('meta[name=\"csrf-token\"]');\n        const token = (input && input.value) || (meta && meta.getAttribute(\"content\")) || \"\";\n        if (token) {\n          cachedCsrf = token;\n          return token;\n        }\n        lastErr = new Error(\"Pas de csrf_token dans \" + url);\n      } catch (e) {\n        lastErr = e;\n        if (/Session Koha absente/.test(String(e.message))) throw e;\n      }\n    }\n    throw lastErr || new Error(\"Impossible de récupérer un jeton CSRF.\");\n  }\n\n  async function restHeaders() {\n    const csrf = cachedCsrf || await fetchFreshCsrfToken();\n    return {\n      \"Content-Type\": \"application/json\",\n      Accept: \"application/json\",\n      \"x-koha-csrf-token\": csrf,\n    };\n  }\n\n  async function resolvePatronId() {\n    if (cachedPatronId) return cachedPatronId;\n    const url = new URL(CONFIG.restBase + \"/patrons\", window.location.origin);\n    url.searchParams.set(\"cardnumber\", CONFIG.patronCardnumber);\n    const resp = await pageFetch(url.toString(), {\n      method: \"GET\",\n      credentials: \"same-origin\",\n      headers: { Accept: \"application/json\" },\n    });\n    const raw = await resp.text();\n    if (!resp.ok) {\n      throw new Error(\n        \"Impossible de résoudre la carte \" + CONFIG.patronCardnumber +\n        \" (HTTP \" + resp.status + \") — \" + extractErrorSnippet(raw)\n      );\n    }\n    let data;\n    try { data = JSON.parse(raw); } catch (e) {\n      throw new Error(\"Réponse patrons non-JSON — \" + extractErrorSnippet(raw));\n    }\n    const list = Array.isArray(data) ? data : (data && data.patrons) || [];\n    if (!list.length) {\n      throw new Error(\"Aucun adhérent trouvé pour la carte \" + CONFIG.patronCardnumber);\n    }\n    const patronId = list[0].patron_id ?? list[0].borrowernumber;\n    if (patronId === undefined || patronId === null) {\n      throw new Error(\"Réponse patrons sans patron_id pour \" + CONFIG.patronCardnumber);\n    }\n    cachedPatronId = Number(patronId);\n    return cachedPatronId;\n  }\n\n  async function fetchCheckoutAvailability(patronId, itemnumber) {\n    const url = new URL(CONFIG.restBase + \"/checkouts/availability\", window.location.origin);\n    url.searchParams.set(\"patron_id\", String(patronId));\n    url.searchParams.set(\"item_id\", String(itemnumber));\n    const resp = await pageFetch(url.toString(), {\n      method: \"GET\",\n      credentials: \"same-origin\",\n      headers: { Accept: \"application/json\" },\n    });\n    const raw = await resp.text();\n    if (!resp.ok) {\n      throw new Error(\n        \"API REST availability a refusé : \" + resp.status + \" \" + raw.slice(0, 300)\n      );\n    }\n    try {\n      return JSON.parse(raw);\n    } catch (e) {\n      throw new Error(\"Réponse availability non-JSON — \" + raw.slice(0, 200));\n    }\n  }\n\n  async function postCheckout(payload, confirmationToken) {\n    const url = new URL(CONFIG.restBase + \"/checkouts\", window.location.origin);\n    if (confirmationToken) url.searchParams.set(\"confirmation\", confirmationToken);\n\n    const doPost = async () => {\n      const resp = await pageFetch(url.toString(), {\n        method: \"POST\",\n        credentials: \"same-origin\",\n        headers: await restHeaders(),\n        body: JSON.stringify(payload),\n      });\n      const raw = await resp.text();\n      return { resp, raw };\n    };\n\n    let { resp, raw } = await doPost();\n    if (!resp.ok && resp.status === 403 && /csrf/i.test(raw)) {\n      cachedCsrf = null;\n      ({ resp, raw } = await doPost());\n    }\n    return { resp, raw };\n  }\n\n  async function issueItem(itemnumber, barcode) {\n    const patronId = await resolvePatronId();\n    const payload = {\n      patron_id: patronId,\n      item_id: Number(itemnumber),\n    };\n    if (CONFIG.libraryId) payload.library_id = CONFIG.libraryId;\n\n    // 1) Disponibilité + éventuel jeton de confirmation (ex. exemplaire perdu)\n    let availability = null;\n    try {\n      availability = await fetchCheckoutAvailability(patronId, itemnumber);\n    } catch (e) {\n      // Anciennes versions sans /availability : on tente le prêt direct\n      console.warn(\"availability indisponible, prêt direct :\", e);\n    }\n\n    if (availability) {\n      const blockers = availability.blockers || {};\n      const blockerKeys = Object.keys(blockers);\n      if (blockerKeys.length) {\n        throw new Error(\n          \"Prêt bloqué par Koha : \" + blockerKeys.join(\", \") +\n          \" — \" + JSON.stringify(blockers).slice(0, 200)\n        );\n      }\n    }\n\n    const confirms = (availability && availability.confirms) || {};\n    const confirmKeys = Object.keys(confirms);\n    const token = availability && availability.confirmation_token;\n\n    // 2) POST avec jeton si des confirmations sont requises (412 sinon)\n    let { resp, raw } = await postCheckout(payload, confirmKeys.length ? token : null);\n\n    // Si 412 sans avoir pu passer par availability, récupérer le token puis réessayer\n    if (resp.status === 412) {\n      availability = await fetchCheckoutAvailability(patronId, itemnumber);\n      const blockers = availability.blockers || {};\n      const blockerKeys = Object.keys(blockers);\n      if (blockerKeys.length) {\n        throw new Error(\n          \"Prêt bloqué par Koha : \" + blockerKeys.join(\", \") +\n          \" — \" + JSON.stringify(blockers).slice(0, 200)\n        );\n      }\n      const retryToken = availability.confirmation_token;\n      if (!retryToken) {\n        throw new Error(\"Confirmation requise (412) mais aucun confirmation_token reçu.\");\n      }\n      ({ resp, raw } = await postCheckout(payload, retryToken));\n    }\n\n    if (!resp.ok) {\n      throw new Error(\"API REST checkouts a refusé : \" + resp.status + \" \" + raw.slice(0, 300));\n    }\n\n    return {\n      via: \"rest\",\n      patron_id: patronId,\n      confirms: Object.keys((availability && availability.confirms) || {}),\n    };\n  }\n\n  async function returnItem(itemnumber, barcode) {\n    // /api/v1/checkin n'existe pas encore sur la plupart des Koha.\n    // L'intranet utilise /cgi-bin/koha/svc/checkin (JSON + session staff).\n    const patronId = await resolvePatronId();\n    const csrf = await fetchFreshCsrfToken();\n\n    const attempts = [\n      // Koha récent : op cud-checkin obligatoire\n      {\n        itemnumber: String(itemnumber),\n        borrowernumber: String(patronId),\n        op: \"cud-checkin\",\n        csrf_token: csrf,\n      },\n      // Koha plus ancien : sans op\n      {\n        itemnumber: String(itemnumber),\n        borrowernumber: String(patronId),\n        csrf_token: csrf,\n      },\n    ];\n\n    let lastErr = null;\n    for (const params of attempts) {\n      const body = new URLSearchParams(params);\n      const resp = await pageFetch(\"/cgi-bin/koha/svc/checkin\", {\n        method: \"POST\",\n        credentials: \"same-origin\",\n        headers: {\n          \"Content-Type\": \"application/x-www-form-urlencoded\",\n          Accept: \"application/json\",\n        },\n        body: body.toString(),\n      });\n      const raw = await resp.text();\n\n      if (!raw || !raw.trim()) {\n        lastErr = new Error(\"svc/checkin : réponse vide (droits circulate / op ?)\");\n        continue;\n      }\n      if (looksLikeLoginPage(raw) || /<html[\\s>]/i.test(raw)) {\n        lastErr = new Error(\"svc/checkin a renvoyé du HTML — \" + extractErrorSnippet(raw));\n        continue;\n      }\n\n      let data;\n      try {\n        data = JSON.parse(raw);\n      } catch (e) {\n        lastErr = new Error(\"svc/checkin non-JSON — \" + raw.slice(0, 200));\n        continue;\n      }\n\n      if (data.returned) {\n        return { via: \"svc/checkin\", data };\n      }\n      lastErr = new Error(\n        \"Retour refusé par Koha (returned=false)\" +\n        (data.itemnumber ? \" pour item \" + data.itemnumber : \"\")\n      );\n    }\n\n    throw lastErr || new Error(\"Échec du retour via svc/checkin\");\n  }\n\n  /* ======================================================================\n   * INTERFACE\n   * ==================================================================== */\n  function parseBarcodes(raw) {\n    return raw\n      .split(/[\\r\\n,;\\t]+/)\n      .map((b) => b.trim())\n      .filter((b) => b.length > 0);\n  }\n\n  async function handleSearch() {\n    const textarea = document.getElementById(\"uds-barcode-input\");\n    const barcodes = parseBarcodes(textarea.value);\n    if (barcodes.length === 0) {\n      showMessage(\"Saisissez ou scannez au moins un code-barres.\", \"error\");\n      return;\n    }\n\n    const tooLong = barcodes.filter((code) => code.length > 20);\n    if (tooLong.length) {\n      showMessage(\"Un code-barres dépasse 20 caractères : \" + tooLong.join(\", \"), \"error\");\n      return;\n    }\n    if (barcodes.length > 100) {\n      showMessage(\"Indiquez au plus 100 codes-barres à la fois.\", \"error\");\n      return;\n    }\n    showMessage(\"Recherche des exemplaires supprimés…\", \"info\");\n    document.getElementById(\"uds-cache-info\").textContent =\n      \"Lecture des exemplaires supprimés pour \" + barcodes.length + \" code(s)…\";\n\n    let data;\n    try {\n      data = await (async () => {\n        const found = await lookupNative('/api/v1/contrib/pmk/restoration/deleted-items', {barcodes});\n        const seen = new Set((found.rows || []).map(item => item.barcode));\n        return {items: found.rows || [], not_found: barcodes.filter(code => !seen.has(code))};\n      })();\n    } catch (e) {\n      showMessage(\"Erreur pendant la recherche : \" + e.message, \"error\");\n      document.getElementById(\"uds-cache-info\").textContent = \"Échec de la recherche.\";\n      return;\n    }\n\n    let found = 0;\n    (data.items || []).forEach((item) => {\n      addRow(item.barcode, item);\n      found++;\n    });\n\n    const notFound = data.not_found || [];\n    textarea.value = \"\";\n    document.getElementById(\"uds-cache-info\").textContent = found + \" exemplaire(s) trouvé(s) dans les exemplaires supprimés.\";\n    syncSelectAllLabel();\n\n    if (notFound.length === 0) {\n      showMessage(found + \" exemplaire(s) trouvé(s) et ajouté(s) à la liste.\", \"info\");\n    } else if (found === 0) {\n      showMessage(\"Aucun exemplaire supprimé trouvé pour : \" + notFound.join(\", \"), \"info\");\n    } else {\n      showMessage(found + \" trouvé(s). Introuvable(s) : \" + notFound.join(\", \"), \"info\");\n    }\n  }\n\n  \n  async function lookupNative(path, query) {\n    const url = new URL(path, window.location.origin);\n    if (query.from) url.searchParams.set('from', query.from);\n    if (query.to) url.searchParams.set('to', query.to);\n    (query.barcodes || []).forEach(code => url.searchParams.append('barcode', code));\n    const response = await pageFetch(url.toString(), {credentials:'same-origin', headers:{Accept:'application/json'}});\n    const value = await response.json().catch(() => ({}));\n    if (!response.ok) {\n      const error = new Error(restoreErrors[value.error] || ('Recherche indisponible (HTTP ' + response.status + ').'));\n      error.code = value.error;\n      throw error;\n    }\n    return value;\n  }\n  async function restorationBiblio(id, options={}) {\n    const response = await pageFetch('/api/v1/contrib/pmk/restoration/biblios/' + encodeURIComponent(id), {\n      credentials:'same-origin', ...options,\n      headers:{Accept:'application/json','Content-Type':'application/json','X-PMK-Request':'1'}\n    });\n    const value = await response.json().catch(() => ({}));\n    if (!response.ok) {\n      const error = new Error(restoreErrors[value.error] || ('Restauration de notice indisponible (HTTP ' + response.status + ').'));\n      error.code = value.error;\n      throw error;\n    }\n    return value;\n  }\n  async function applyBiblio(plan) {\n    const result = await restorationBiblio(plan.biblio_id, {method:'POST', body:JSON.stringify({fingerprint:plan.fingerprint, confirmed:true, biblio_id:plan.biblio_id})});\n    if (!result.restored || Number(result.biblio_id) !== Number(plan.biblio_id)) throw new Error('La restauration de la notice n’a pas été confirmée.');\n    return result;\n  }\n\n  async function handleDateSearch() {\n    const biblios = wantsBiblios();\n    const fromDate = document.getElementById('uds-from-date').value;\n    const toDate = document.getElementById('uds-to-date').value;\n    if (!fromDate) {\n      showMessage('Indiquez au moins la date de début.', 'error');\n      return;\n    }\n    if (toDate && fromDate > toDate) {\n      showMessage('La date de début est postérieure à la date de fin.', 'error');\n      return;\n    }\n    showMessage(biblios ? 'Chargement des notices supprimées…' : 'Chargement des exemplaires supprimés…', 'info');\n    let items = [];\n    let truncated = false;\n    try {\n      const found = await lookupNative(biblios ? '/api/v1/contrib/pmk/restoration/deleted-biblios' : '/api/v1/contrib/pmk/restoration/deleted-items', {from: fromDate, to: toDate});\n      items = found.rows || [];\n      truncated = !!found.truncated;\n    } catch (e) {\n      showMessage('Erreur pendant le chargement : ' + e.message, 'error');\n      document.getElementById('uds-cache-info').textContent = 'Échec du chargement par dates.';\n      return;\n    }\n    document.getElementById('uds-table-body').innerHTML = '';\n    rows.clear();\n    syncSelectAllLabel();\n    items.forEach(item => {\n      if (biblios || item.kind === 'biblio') addRow('Notice ' + item.biblionumber, Object.assign({kind:'biblio', conflict:false}, item));\n      else addRow(item.barcode, item);\n    });\n    const label = biblios ? ' notice(s) supprimée(s)' : ' exemplaire(s) supprimé(s)';\n    document.getElementById('uds-cache-info').textContent = items.length + label + ' (' + fromDate + ' → ' + (toDate || 'maintenant') + ').' + (truncated ? ' Période trop large : affinez-la, 1000 dossiers maximum.' : '');\n    showMessage(items.length ? items.length + ' dossier(s) chargé(s).' : 'Aucun dossier supprimé sur cette plage. Ce n’est pas une erreur de recherche.', 'info');\n    syncSelectAllLabel();\n  }\n\n  function wantsBiblios() {\n    const checked = document.querySelector('input[name=\"uds-date-target\"]:checked');\n    return !!(checked && checked.value === 'biblios');\n  }\n\n  function updateTargetUI() {\n    const biblios = wantsBiblios();\n    document.querySelectorAll('#uds-target label').forEach(label => {\n      const input = label.querySelector('input[type=\"radio\"]');\n      label.classList.toggle('uds-mode-active', !!(input && input.checked));\n    });\n    const note = document.getElementById('uds-target-note');\n    if (note) note.textContent = biblios\n      ? 'Les notices sont les fiches du catalogue. Les restaurer ne ramène pas leurs exemplaires supprimés.'\n      : 'Les exemplaires sont les documents. Si leur notice est aussi supprimée, elle est restaurée avec eux.';\n    const button = document.getElementById('uds-search-dates');\n    if (button) button.textContent = biblios ? 'Charger les notices' : 'Charger les exemplaires';\n  }\n\n  function getSearchMode() {\n    const checked = document.querySelector('input[name=\"uds-search-mode\"]:checked');\n    return (checked && checked.value) || \"barcode\";\n  }\n\n    function updateModeUI() {\n    const mode = getSearchMode();\n    document.querySelectorAll('#uds-mode label').forEach(label => {\n      const input = label.querySelector('input[type=\"radio\"]');\n      label.classList.toggle('uds-mode-active', !!(input && input.checked));\n    });\n    document.getElementById('uds-panel-barcode').hidden = mode !== 'barcode';\n    document.getElementById('uds-panel-dates').hidden = mode === 'barcode';\n    updateTargetUI();\n    const biblios = wantsBiblios();\n    document.getElementById('uds-cache-info').textContent = mode === 'barcode'\n      ? 'Mode code-barres — lecture directe des exemplaires supprimés.'\n      : (biblios\n        ? 'Mode date — notices supprimées. Leurs exemplaires ne sont pas restaurés.'\n        : 'Mode date — exemplaires supprimés. Leur notice est restaurée si elle l’est aussi.');\n  }\n\n  /* ======================================================================\n   * CONTRÔLE D'ACCÈS — droits Koha et liste facultative\n   * ==================================================================== */\n  async function detectLoggedInUsername() {\n    const resp = await pageFetch(\"/cgi-bin/koha/mainpage.pl\", { credentials: \"same-origin\" });\n    const html = await resp.text();\n    if (!resp.ok) {\n      throw new Error(\"Impossible de vérifier la session (HTTP \" + resp.status + \")\");\n    }\n    if (looksLikeLoginPage(html)) {\n      throw new Error(\"Session Koha absente — connectez-vous sur l'intranet.\");\n    }\n    const doc = new DOMParser().parseFromString(html, \"text/html\");\n    const withData = doc.querySelector(\"[data-loggedinusername]\");\n    if (withData && withData.getAttribute(\"data-loggedinusername\")) {\n      return withData.getAttribute(\"data-loggedinusername\").trim();\n    }\n    const spans = Array.from(doc.querySelectorAll(\".loggedinusername\"));\n    for (const span of spans) {\n      const name = (span.textContent || \"\").trim();\n      if (name) return name;\n    }\n    throw new Error(\"Impossible de lire l'utilisateur connecté dans la page Koha.\");\n  }\n\n  async function enforceAccess() {\n    const statusEl = document.getElementById(\"uds-auth-status\");\n    const appEl = document.getElementById(\"uds-app\");\n    const deniedEl = document.getElementById(\"uds-denied\");\n    try {\n      const username = await detectLoggedInUsername();\n      const allowed = CONFIG.allowedUsernames.map((u) => u.toLowerCase());\n      if (allowed.length && !allowed.includes(username.toLowerCase())) {\n        statusEl.textContent = \"Connecté en tant que « \" + username + \" » — accès refusé.\";\n        deniedEl.hidden = false;\n        appEl.hidden = true;\n        return false;\n      }\n      statusEl.textContent = \"Connecté en tant que « \" + username + \" » — accès autorisé.\";\n      deniedEl.hidden = true;\n      appEl.hidden = false;\n      return true;\n    } catch (e) {\n      statusEl.textContent = \"Contrôle d'accès : \" + e.message;\n      deniedEl.hidden = false;\n      appEl.hidden = true;\n      return false;\n    }\n  }\n\n  function formatStatut(value) {\n    const v = String(value ?? \"\").trim();\n    if (!v || v === \"0\") return \"—\";\n    return v;\n  }\n\n  function addRow(barcode, data) {\n    if (rows.has(barcode)) {\n      rows.get(barcode).el.remove();\n      rows.delete(barcode);\n    }\n    const tbody = document.getElementById(\"uds-table-body\");\n    const tr = document.createElement(\"tr\");\n    tr.dataset.barcode = barcode;\n\n    const conflictNote = data.conflict\n      ? '<div class=\"uds-conflict\">Ce code-barres existe déjà. Un nouveau code sera proposé dans l’aperçu, avant confirmation.</div>'\n      : \"\";\n\n    tr.innerHTML = `\n      <td><input type=\"checkbox\" checked /></td>\n      <td><strong>${esc(barcode)}</strong>${conflictNote}</td>\n      <td>${esc(data.title)}<br/><em>${esc(data.author)}</em></td>\n      <td>${esc(data.isbn)}${data.issn ? \" / \" + esc(data.issn) : \"\"}</td>\n      <td>N° ${esc(data.biblionumber)}</td>\n      <td>${esc(data.timestamp)}</td>\n      <td>${esc(formatStatut(data.statut))}</td>\n      <td>${esc(formatStatut(data.statut_perdu))}</td>\n      <td><span class=\"uds-status uds-status--wait\">En attente</span></td>\n      <td>\n        <div class=\"uds-actions\">\n          <button class=\"uds-btn uds-btn--restore\" data-action=\"restore\">Restaurer</button>\n          <button class=\"uds-btn uds-btn--issue\" data-action=\"issue\" disabled>Prêter</button>\n          <button class=\"uds-btn uds-btn--return\" data-action=\"return\" disabled>Retourner</button>\n          <button class=\"uds-btn uds-btn--cycle\" data-action=\"cycle\">Prêter et retourner</button>\n        </div>\n        <div class=\"uds-log\"></div>\n      </td>\n    `;\n\n    tr.querySelector('[data-action=\"restore\"]').addEventListener(\"click\", () => doRestore(barcode).catch(e=>showMessage(e.message,'error')));\n    tr.querySelector('[data-action=\"issue\"]').addEventListener(\"click\", () => doIssue(barcode).catch(e=>showMessage(e.message,'error')));\n    tr.querySelector('[data-action=\"return\"]').addEventListener(\"click\", () => doReturn(barcode).catch(e=>showMessage(e.message,'error')));\n    tr.querySelector('[data-action=\"cycle\"]').addEventListener(\"click\", () => runOnSelection(true, [barcode]).catch(e=>showMessage(e.message,'error')));\n\n    tbody.appendChild(tr);\n    if(data.kind==='biblio'){tr.querySelector('[data-action=\"issue\"]').hidden=true;tr.querySelector('[data-action=\"return\"]').hidden=true;tr.querySelector('[data-action=\"cycle\"]').hidden=true;}\n    rows.set(barcode, { data, el: tr });\n    syncSelectAllLabel();\n  }\n\n  async function doRestore(barcode, approvedPlan) {\n    const row = rows.get(barcode);\n    if (!row) return;\n    if(row.restored)return;\n    if(row.restoring)throw new Error(\"Une restauration est déjà en cours pour cet exemplaire.\");\n    row.restoring=true;\n    setStatus(barcode, \"Restauration…\", \"busy\");\n    log(barcode, \"→ Restauration de l'exemplaire \" + row.data.itemnumber);\n    try {\n      // Après une réponse perdue, le serveur vérifie le reçu de la même opération.\n      if(!row.pendingPlan){\n        const plan=approvedPlan||(row.data.kind==='biblio'?await restorationBiblio(row.data.biblionumber):await restorationRequest(row.data.itemnumber));\n        if(!approvedPlan&&!await confirmRestoration([plan])){setStatus(barcode,\"Annulé\",\"info\");return;}\n        row.pendingPlan=plan;\n      }\n      const confirmations = [row.data.kind==='biblio' ? await applyBiblio(row.pendingPlan) : await applyRestoration(row.pendingPlan)];\n      row.restored=true;row.pendingPlan=null;\n      setStatus(barcode, \"Restauré\", \"ok\");\n      confirmations.forEach((c) => {row.data.actualBarcode=c.barcode;log(barcode, \"Fait — exemplaire \"+c.item_id+\" restauré, code-barres : \"+(c.barcode||\"aucun\"));});\n      row.el.querySelector('[data-action=\"restore\"]').disabled = true;\n      if(row.data.kind!=='biblio')row.el.querySelector('[data-action=\"issue\"]').disabled = false;\n    } catch (e) {\n      if(['preview_changed','item_changed','deleted_item_missing'].includes(e.code))row.pendingPlan=null;\n      setStatus(barcode, \"Erreur restauration\", \"error\");\n      log(barcode, \"Échec — \" + e.message);\n      throw e;\n    } finally { row.restoring=false; }\n  }\n\n  async function doIssue(barcode) {\n    const row = rows.get(barcode);\n    if (!row || row.issued) return;\n    if (!String(CONFIG.patronCardnumber || \"\").trim()) {\n      setStatus(barcode, \"Carte manquante\", \"error\");\n      throw new Error(\"Renseignez une carte technique avant un traitement avec prêt/retour.\");\n    }\n    setStatus(barcode, \"Prêt en cours…\", \"busy\");\n    log(barcode, \"→ Prêt API REST — carte \" + CONFIG.patronCardnumber);\n    try {\n      const result = await issueItem(row.data.itemnumber, row.data.actualBarcode||barcode);\n      row.issued=true;\n      setStatus(barcode, \"Prêté\", \"ok\");\n      const confirmNote = (result.confirms && result.confirms.length)\n        ? \" [confirmé : \" + result.confirms.join(\", \") + \"]\"\n        : \"\";\n      log(barcode, \"Fait — prêté (lecteur \" + result.patron_id + \")\" + confirmNote);\n      row.el.querySelector('[data-action=\"issue\"]').disabled = true;\n      row.el.querySelector('[data-action=\"return\"]').disabled = false;\n    } catch (e) {\n      setStatus(barcode, \"Erreur prêt\", \"error\");\n      log(barcode, \"Échec — \" + e.message);\n      throw e;\n    }\n  }\n\n  async function doReturn(barcode) {\n    const row = rows.get(barcode);\n    if (!row || row.returned) return;\n    setStatus(barcode, \"Retour en cours…\", \"busy\");\n    log(barcode, \"→ Retour API REST\");\n    try {\n      await returnItem(row.data.itemnumber, row.data.actualBarcode||barcode);\n      row.returned=true;\n      setStatus(barcode, \"Retourné\", \"ok\");\n      log(barcode, \"Fait — retour enregistré\");\n      row.el.querySelector('[data-action=\"return\"]').disabled = true;\n    } catch (e) {\n      setStatus(barcode, \"Erreur retour\", \"error\");\n      log(barcode, \"Échec — \" + e.message);\n      throw e;\n    }\n  }\n\n  function getSelectedBarcodes() {\n    return Array.from(document.querySelectorAll(\"#uds-table-body input[type=checkbox]:checked\")).map(b=>b.closest(\"tr\").dataset.barcode);\n  }\n  let selectionBusy=false;\n  async function runOnSelection(pipeline=false, only) {\n    if(selectionBusy)return;\n    if (pipeline && !String(CONFIG.patronCardnumber || \"\").trim()) {\n      showMessage(\"Renseignez une carte technique avant un traitement avec prêt/retour.\", \"error\");\n      return;\n    }\n    const picked = Array.isArray(only) ? only : getSelectedBarcodes();\n    const barcodes=picked.filter(barcode=>{const row=rows.get(barcode);return row && !(pipeline?row.returned:row.restored);});\n    if(!barcodes.length){showMessage(\"Aucun exemplaire coché restant à traiter.\",\"info\");return;}\n    selectionBusy=true;\n    const controls=Array.from(document.querySelectorAll('#uds-actionsbar button, #uds-check-all, #uds-search, #uds-search-dates, #uds-table-body button, #uds-table-body input[type=checkbox]'));\n    const disabled=controls.map(el=>el.disabled);controls.forEach(el=>el.disabled=true);\n    try {\n      const plans=new Map();\n      for(const barcode of barcodes){const row=rows.get(barcode);if(!row.restored)plans.set(barcode,row.pendingPlan||(row.data.kind==='biblio'?await restorationBiblio(row.data.biblionumber):await restorationRequest(row.data.itemnumber)));}\n      if(!await confirmRestoration([...plans.values()],pipeline)){showMessage(\"Traitement annulé ; aucune donnée modifiée.\",\"info\");return;}\n      const action=async barcode=>{await doRestore(barcode,plans.get(barcode));if(pipeline && rows.get(barcode).data.kind!=='biblio'){await doIssue(barcode);await doReturn(barcode);}rows.get(barcode).el.querySelector('input[type=checkbox]').checked=false;};\n      let result;\n      if(window.PMKWorkbench)result=await PMKWorkbench.batch(barcodes,action,{key:x=>x,onProgress:r=>showMessage((r.completed+r.failed)+\" / \"+barcodes.length+\" traité(s)…\",\"info\")});\n      else {result={completed:0,failed:0};for(const barcode of barcodes){try{await action(barcode);result.completed++;}catch(_){result.failed++;}}}\n      showMessage(`Traitement terminé : ${result.completed} réussi(s), ${result.failed} en erreur. Les échecs restent cochés pour une nouvelle tentative.`,result.failed?\"error\":\"info\");\n    } catch(e){showMessage(e.message,\"error\");}\n    finally {\n      controls.forEach((el,i)=>el.disabled=disabled[i]);\n      for(const row of rows.values()){\n        row.el.querySelector('[data-action=\"restore\"]').disabled=!!row.restored;\n        row.el.querySelector('[data-action=\"issue\"]').disabled=!row.restored||!!row.issued;\n        row.el.querySelector('[data-action=\"return\"]').disabled=!row.issued||!!row.returned;\n        row.el.querySelector('[data-action=\"cycle\"]').disabled=!!row.returned;\n      }\n      selectionBusy=false;\n      syncSelectAllLabel();\n    }\n  }\n\n  document.getElementById(\"uds-search\").addEventListener(\"click\", handleSearch);\n  document.getElementById(\"uds-search-dates\").addEventListener(\"click\", handleDateSearch);\n\n  document.getElementById(\"uds-barcode-input\").addEventListener(\"keydown\", (e) => {\n    if (e.key === \"Enter\" && (e.ctrlKey || e.metaKey)) {\n      e.preventDefault();\n      handleSearch();\n    }\n  });\n\n  document.querySelectorAll('input[name=\"uds-search-mode\"]').forEach((input) => {\n    input.addEventListener(\"change\", updateModeUI);\n  });\n  document.querySelectorAll('input[name=\"uds-date-target\"]').forEach((input) => {\n    input.addEventListener(\"change\", updateTargetUI);\n  });\n\n  document.getElementById(\"uds-table-body\").addEventListener(\"change\", (event) => {\n    if (event.target.matches('input[type=\"checkbox\"]')) syncSelectAllLabel();\n  });\n\n  document.getElementById(\"uds-check-all\").addEventListener(\"change\", () => {\n    setAllChecked(document.getElementById(\"uds-check-all\").checked);\n  });\n\n  document.getElementById(\"uds-select-all\").addEventListener(\"click\", () => {\n    const boxes = Array.from(document.querySelectorAll(\"#uds-table-body input[type=checkbox]\"));\n    setAllChecked(!(boxes.length && boxes.every((box) => box.checked)));\n  });\n\n  document.getElementById(\"uds-batch-restore\").addEventListener(\"click\", () => {\n    runOnSelection(false);\n  });\n\n  document.getElementById(\"uds-batch-pipeline\").addEventListener(\"click\", () => {\n    runOnSelection(true);\n  });\n\n  document.getElementById(\"uds-from-date\").value = daysAgoISO(CONFIG.defaultLookbackDays);\n  document.getElementById(\"uds-to-date\").value = todayISO();\n  updateModeUI();\n\n  enforceAccess().then((ok) => {\n    if (ok) document.getElementById(\"uds-barcode-input\").focus();\n  });\n})();\n</script>\n";
    window.PMKPages.register({
        id:"restore-deleted-items",
        title:"Restauration d’exemplaires",
        async mount(container, context){
            await context.mountLegacyHtml(container, PAGE_SOURCE);        }
    });
})(window);
